//! Channel registry: the single source of truth for every canonical channel (D-017).
//!
//! The table below drives the protocol (TLV channel ids), the recorder, graph selectors, export column
//! names, UI labels, validation ranges and `docs/CHANNEL_IDS.md` (generated by a golden-file test).
//!
//! Rules:
//! - IDs are append-only and never reused. They are allocated by group (high byte, see [`ChannelGroup`]).
//!   Per-wheel channels use a stride of 4 (`FL, FR, RL, RR` = `base + 0..=3`), see [`wheel_group`].
//! - Canonical names follow docs/LMU_CHANNEL_MAP.md §0.1 (`group.quantity_unitsuffix`); export names are
//!   MoTeC-style (`Speed`, `TyrePressure_FL`, `TyreTemp_FL_Inner`).
//! - `Measured` means "directly from LMU after unit conversion only". Every measured shared-memory origin is
//!   checked against `docs/research/lmu_abi_layout.json` by `tests/registry_docs.rs`.
//! - Validation ranges are conservative: they reject physically impossible values (garbage, torn reads,
//!   unit mix-ups) but never real extremes such as crashes, spins or lock-ups. Where LMU_CHANNEL_MAP gives a
//!   tighter range that a real car can exceed (spins, reversing at speed), the range here is wider.
//! - `value_type` is the wire/storage type. LMU doubles are stored as F32 only where f32 resolution is far
//!   finer than the physical resolution that matters (temperatures, pressures, forces, inputs…); times,
//!   world positions and distances stay F64. The raw snapshot recorder keeps the original doubles.

use std::f64::consts::{FRAC_PI_2, PI};
use std::fmt::Write as _;

use serde::{Deserialize, Serialize};

use crate::TELEMETRY_SCHEMA_VERSION;
use crate::channel::{
    Availability, ChannelDef, ChannelId, FrequencyClass, Interpolation, Priority, Provenance,
    Source,
};
use crate::units::{KELVIN_OFFSET, RAD_PER_DEG, Unit as U};
use crate::value::{Sample, ValueType as T};

// ---------------------------------------------------------------------------------------------------------
// Plausibility limits shared by several channels (internal SI units).
// ---------------------------------------------------------------------------------------------------------

/// Vehicle speed bound (m/s, 540 km/h): far above any LMU car, far below garbage.
const MAX_SPEED_MPS: f64 = 150.0;
/// Rate bound for body speeds (m/s², about 150 g). Crash decelerations in the sim stay below it; a torn or
/// garbage read (e.g. 78 → -194 m/s in 10 ms) exceeds it by an order of magnitude.
const MAX_BODY_ACCEL_MPS2: f64 = 1_500.0;
/// Raw local acceleration bound (m/s², 50 g; LMU_CHANNEL_MAP §9).
const MAX_ACCEL_MPS2: f64 = 490.0;
/// Derived G bound (g). The map flags > 6 g as SUSPECT, but impacts legitimately exceed it, so only values
/// beyond the raw acceleration bound are rejected.
const MAX_G: f64 = 50.0;
/// Angular rate bound (rad/s). Spins exceed the map's ±5 rad/s for derived rates, so the raw bound is used.
const MAX_ANGULAR_RATE_RADPS: f64 = 20.0;
/// Angular acceleration bound (rad/s²).
const MAX_ANGULAR_ACCEL_RADPS2: f64 = 500.0;
/// Position change bound (m/s): above the speed bound so legitimate motion never trips it; a teleport (reset
/// to the garage) produces exactly one rejected sample.
const MAX_POSITION_RATE_MPS: f64 = 200.0;
/// World coordinate bound (m).
const MAX_WORLD_COORD_M: f64 = 1.0e5;
/// Orientation matrix element bound (rows are unit vectors, ±0.01 tolerance).
const ORIENTATION_MAX: f64 = 1.01;
/// Pedal fraction tolerance below 0 / above 1.
const PEDAL_MIN: f64 = -0.01;
const PEDAL_MAX: f64 = 1.01;
/// Signed steering input bound.
const STEERING_MAX: f64 = 1.01;
/// Physical steering wheel range bound: 1440° lock-to-lock (A-LMU-037).
const MAX_STEERING_RANGE_RAD: f64 = 1_440.0 * RAD_PER_DEG;
/// Steering wheel angle bound: half the maximum range.
const MAX_STEERING_ANGLE_RAD: f64 = MAX_STEERING_RANGE_RAD / 2.0;
/// Highest forward gear accepted.
const MAX_GEARS: f64 = 10.0;
/// Engine speed bounds (rpm): 1.2 × the highest rev limit accepted (25 000), and a small negative margin.
const MIN_RPM: f64 = -1_000.0;
const MAX_RPM: f64 = 30_000.0;
/// Water/oil temperature bounds (°C) and rate (°C/s).
const FLUID_TEMP_MIN_C: f64 = -40.0;
const FLUID_TEMP_MAX_C: f64 = 200.0;
const FLUID_TEMP_RATE_C_PER_S: f64 = 50.0;
/// Hybrid motor/cooler temperature rate (°C/s).
const HYBRID_TEMP_RATE_C_PER_S: f64 = 100.0;
/// Tyre temperatures: raw 200..700 K (LMU_CHANNEL_MAP §11) in °C.
const TYRE_TEMP_MIN_C: f64 = 200.0 - KELVIN_OFFSET;
const TYRE_TEMP_MAX_C: f64 = 700.0 - KELVIN_OFFSET;
/// Tyre temperature rates (°C/s): surface spikes on lock-ups, inner layer and carcass react more slowly.
const TYRE_SURFACE_TEMP_RATE: f64 = 3_000.0;
const TYRE_LAYER_TEMP_RATE: f64 = 1_000.0;
const TYRE_CARCASS_TEMP_RATE: f64 = 500.0;
/// Optimal tyre temperature bound (°C).
const TYRE_OPTIMAL_TEMP_MAX_C: f64 = 200.0;
/// Inner-minus-outer spread bound (°C).
const TYRE_SPREAD_MAX_C: f64 = 100.0;
/// Tyre pressure bound (Pa, raw 600 kPa) and rate (Pa/s; a puncture is allowed, a teleport is not).
const MAX_TYRE_PRESSURE_PA: f64 = 600_000.0;
const TYRE_PRESSURE_RATE_PA_PER_S: f64 = 2.0e6;
/// Tyre load and force bounds (N).
const MAX_TYRE_LOAD_N: f64 = 60_000.0;
const MAX_TYRE_FORCE_N: f64 = 60_000.0;
/// Tyre wear rate (fraction/s); a tyre change is a step (one rejected sample).
const WEAR_RATE_FRAC_PER_S: f64 = 0.5;
/// Brake temperature bounds (°C) and rate (°C/s).
const BRAKE_TEMP_MIN_C: f64 = -50.0;
const BRAKE_TEMP_MAX_C: f64 = 1_500.0;
const BRAKE_TEMP_RATE_C_PER_S: f64 = 3_000.0;
/// Fraction with 1 % tolerance above full scale (brake pressure, fuel level fraction).
const FRACTION_TOLERANT_MAX: f64 = 1.01;
/// Ride height bounds (m).
const RIDE_HEIGHT_MIN_M: f64 = -0.05;
const RIDE_HEIGHT_MAX_M: f64 = 0.3;
/// Fuel: capacity bound, level bound (capacity + 1 L) and rate (L/s; refuelling allowed, teleports not).
const MAX_FUEL_CAPACITY_L: f64 = 200.0;
const MAX_FUEL_LEVEL_L: f64 = MAX_FUEL_CAPACITY_L + 1.0;
const FUEL_RATE_L_PER_S: f64 = 50.0;
/// Fuel used per lap bound (L).
const MAX_FUEL_PER_LAP_L: f64 = 50.0;
/// Fuel needed to the end of a session bound (L; a 24 h race needs a few thousand litres).
const MAX_FUEL_TO_FINISH_L: f64 = 20_000.0;
/// Energy fraction rate (fraction/s); refills are steps.
const ENERGY_RATE_FRAC_PER_S: f64 = 1.0;
/// Virtual energy used per lap bound (fraction).
const MAX_VE_PER_LAP_FRAC: f64 = 0.5;
/// Lap and session time bounds (s).
const MAX_LAP_TIME_S: f64 = 3_600.0;
const MAX_SESSION_TIME_S: f64 = 1.0e7;
/// Delta-to-best bound (s).
const MAX_DELTA_S: f64 = 600.0;
/// Physics update interval bound (s).
const MAX_UPDATE_DELTA_S: f64 = 0.5;
/// Seconds per day (time-of-day channels).
const SECONDS_PER_DAY: f64 = 86_400.0;
/// Lap count bound.
const MAX_LAPS: f64 = 100_000.0;
/// Stint count bound.
const MAX_STINTS: f64 = 1_000.0;
/// Vehicle slots in `LMU_Data`.
const MAX_VEHICLES: f64 = 104.0;
/// Pit stop and penalty count bounds.
const MAX_PIT_STOPS: f64 = 100.0;
const MAX_PENALTIES: f64 = 100.0;
/// Track length bounds (m) and the lap-distance slack around them.
const MIN_TRACK_LENGTH_M: f64 = 500.0;
const MAX_TRACK_LENGTH_M: f64 = 30_000.0;
const LAP_DIST_SLACK_M: f64 = 50.0;
/// Total race distance bound (m).
const MAX_TOTAL_DISTANCE_M: f64 = 1.0e8;
/// Wheel rotation bound (rad/s): ~1100 km/h at a 0.33 m radius, so wheelspin at top speed never trips it.
const MAX_WHEEL_ROT_RADPS: f64 = 1_000.0;
/// Wind speed bound (m/s).
const MAX_WIND_MPS: f64 = 60.0;
/// Largest positive `long` (game version).
const I32_MAX_F64: f64 = i32::MAX as f64;

// ---------------------------------------------------------------------------------------------------------
// Table builder
// ---------------------------------------------------------------------------------------------------------

/// A channel definition without its identity (id, names), built with `const fn` modifiers.
#[derive(Clone, Copy)]
struct Draft {
    label: &'static str,
    unit: U,
    value_type: T,
    source: Source,
    provenance: Provenance,
    priority: Priority,
    frequency: FrequencyClass,
    interpolation: Interpolation,
    availability: Availability,
    origin: &'static str,
    valid_range: Option<(f64, f64)>,
    max_rate_per_s: Option<f64>,
}

const fn draft(
    label: &'static str,
    unit: U,
    value_type: T,
    source: Source,
    provenance: Provenance,
    frequency: FrequencyClass,
    origin: &'static str,
) -> Draft {
    // Floats may be interpolated for display by default; integers, booleans, enums and text never are.
    let interpolation = match value_type {
        T::F32 | T::F64 => Interpolation::Continuous,
        _ => Interpolation::Discrete,
    };
    Draft {
        label,
        unit,
        value_type,
        source,
        provenance,
        priority: Priority::P1,
        frequency,
        interpolation,
        availability: Availability::Always,
        origin,
        valid_range: None,
        max_rate_per_s: None,
    }
}

/// Measured, telemetry block, every telemetry update.
const fn tel(label: &'static str, unit: U, value_type: T, origin: &'static str) -> Draft {
    let src = Source::LmuSharedMemoryTelemetry;
    draft(
        label,
        unit,
        value_type,
        src,
        Provenance::Measured,
        FrequencyClass::Physics,
        origin,
    )
}

/// Measured, scoring block, every scoring update.
const fn sco(label: &'static str, unit: U, value_type: T, origin: &'static str) -> Draft {
    let src = Source::LmuSharedMemoryScoring;
    draft(
        label,
        unit,
        value_type,
        src,
        Provenance::Measured,
        FrequencyClass::Scoring,
        origin,
    )
}

/// Measured, generic/application block.
const fn generic(label: &'static str, unit: U, value_type: T, origin: &'static str) -> Draft {
    let src = Source::LmuSharedMemoryGeneric;
    draft(
        label,
        unit,
        value_type,
        src,
        Provenance::Measured,
        FrequencyClass::Physics,
        origin,
    )
}

/// Derived by `race-engines` / `lmu-normalizer` (origin `formula:<id>`).
const fn calc(label: &'static str, unit: U, value_type: T, origin: &'static str) -> Draft {
    draft(
        label,
        unit,
        value_type,
        Source::Calculated,
        Provenance::Derived,
        FrequencyClass::Physics,
        origin,
    )
}

/// Application diagnostics (origin `app:<id>`).
const fn app(label: &'static str, unit: U, value_type: T, origin: &'static str) -> Draft {
    let freq = FrequencyClass::Diagnostic;
    draft(
        label,
        unit,
        value_type,
        Source::Application,
        Provenance::Derived,
        freq,
        origin,
    )
}

/// A channel no live source provides (LMU_CHANNEL_MAP §19); `source` is where it might come from.
const fn missing(
    label: &'static str,
    unit: U,
    value_type: T,
    source: Source,
    origin: &'static str,
) -> Draft {
    let frequency = match source {
        Source::LmuSharedMemoryScoring => FrequencyClass::Scoring,
        Source::LmuRest => FrequencyClass::Environment,
        _ => FrequencyClass::Physics,
    };
    let mut d = draft(
        label,
        unit,
        value_type,
        source,
        Provenance::Measured,
        frequency,
        origin,
    );
    d.availability = Availability::NotProvided;
    d
}

impl Draft {
    const fn p0(mut self) -> Self {
        self.priority = Priority::P0;
        self
    }
    const fn p2(mut self) -> Self {
        self.priority = Priority::P2;
        self
    }
    const fn discrete(mut self) -> Self {
        self.interpolation = Interpolation::Discrete;
        self
    }
    /// Static per session (never interpolated).
    const fn stat(mut self) -> Self {
        self.frequency = FrequencyClass::Static;
        self.interpolation = Interpolation::Discrete;
        self
    }
    /// Event-driven step value (never interpolated).
    const fn event(mut self) -> Self {
        self.frequency = FrequencyClass::Event;
        self.interpolation = Interpolation::Discrete;
        self
    }
    const fn scoring(mut self) -> Self {
        self.frequency = FrequencyClass::Scoring;
        self
    }
    const fn env(mut self) -> Self {
        self.frequency = FrequencyClass::Environment;
        self
    }
    const fn estimated(mut self) -> Self {
        self.provenance = Provenance::Estimated;
        self
    }
    /// Vehicle-dependent availability.
    const fn vd(mut self) -> Self {
        self.availability = Availability::VehicleDependent;
        self
    }
    const fn experimental(mut self) -> Self {
        self.availability = Availability::Experimental;
        self
    }
    const fn range(mut self, lo: f64, hi: f64) -> Self {
        self.valid_range = Some((lo, hi));
        self
    }
    /// Lower bound only.
    const fn min(mut self, lo: f64) -> Self {
        self.valid_range = Some((lo, f64::INFINITY));
        self
    }
    const fn rate(mut self, max_per_s: f64) -> Self {
        self.max_rate_per_s = Some(max_per_s);
        self
    }
    const fn finish(
        self,
        id: ChannelId,
        name: &'static str,
        export_name: &'static str,
    ) -> ChannelDef {
        ChannelDef {
            id,
            name,
            export_name,
            label: self.label,
            unit: self.unit,
            value_type: self.value_type,
            source: self.source,
            provenance: self.provenance,
            priority: self.priority,
            frequency: self.frequency,
            interpolation: self.interpolation,
            availability: self.availability,
            origin: self.origin,
            valid_range: self.valid_range,
            max_rate_per_s: self.max_rate_per_s,
        }
    }
}

/// `telemetry.telemInfo[player].<field>`
macro_rules! tp {
    ($field:literal) => {
        concat!("telemetry.telemInfo[player].", $field)
    };
}
/// `scoring.vehScoringInfo[player].<field>`
macro_rules! sp {
    ($field:literal) => {
        concat!("scoring.vehScoringInfo[player].", $field)
    };
}
/// `scoring.scoringInfo.<field>`
macro_rules! si {
    ($field:literal) => {
        concat!("scoring.scoringInfo.", $field)
    };
}

/// Generates, from one list: the `ch` id constants, the sorted table, and name/export-name lookups whose
/// `match` arms make a duplicate canonical or export name a compile error (`unreachable_patterns`).
macro_rules! registry {
    ( $( $konst:ident = $id:literal, $name:literal, $export:literal => $draft:expr ; )+ ) => {
        /// Channel id constants for code use, e.g. `ch::SPEED`, `ch::TYRE_PRESSURE_FL`.
        pub mod ch {
            use crate::channel::ChannelId;
            $(
                #[doc = concat!("`", $name, "` (export `", $export, "`)")]
                pub const $konst: ChannelId = ChannelId($id);
            )+
        }

        const TABLE: &[ChannelDef] = &[ $( $draft.finish(ChannelId($id), $name, $export), )+ ];

        #[deny(unreachable_patterns)]
        fn id_by_name(name: &str) -> Option<ChannelId> {
            match name {
                $( $name => Some(ChannelId($id)), )+
                _ => None,
            }
        }

        #[deny(unreachable_patterns)]
        fn id_by_export_name(export_name: &str) -> Option<ChannelId> {
            match export_name {
                $( $export => Some(ChannelId($id)), )+
                _ => None,
            }
        }
    };
}

