// ---------------------------------------------------------------------------------------------------------
// Compile-time invariants
// ---------------------------------------------------------------------------------------------------------

/// Panics at compile time if the table is not sorted by id, uses the reserved id 0, leaves a group range,
/// or carries an empty/inverted range or a non-positive rate.
const fn check_table(table: &[ChannelDef]) {
    let mut i = 0;
    while i < table.len() {
        let def = &table[i];
        assert!(def.id.0 != 0, "channel id 0 is reserved");
        assert!(
            ChannelGroup::of(def.id).is_some(),
            "channel id outside every group range"
        );
        if i > 0 {
            assert!(
                table[i - 1].id.0 < def.id.0,
                "registry ids must be strictly increasing (sorted, unique)"
            );
        }
        if let Some((lo, hi)) = def.valid_range {
            assert!(lo < hi, "valid_range must satisfy lo < hi");
        }
        if let Some(rate) = def.max_rate_per_s {
            assert!(rate > 0.0, "max_rate_per_s must be positive");
        }
        i += 1;
    }
}

const _: () = check_table(TABLE);

/// All channel definitions, sorted by id. A frame's dense sample vector is indexed by position in this
/// slice ([`index_of`]).
pub static CHANNELS: &[ChannelDef] = TABLE;

// ---------------------------------------------------------------------------------------------------------
// Lookups
// ---------------------------------------------------------------------------------------------------------

/// All channel definitions, sorted by id.
pub fn all() -> &'static [ChannelDef] {
    CHANNELS
}

/// Number of channels.
pub fn len() -> usize {
    CHANNELS.len()
}

/// Dense position of `id` (binary search over the sorted table).
pub fn index_of(id: ChannelId) -> Option<usize> {
    CHANNELS.binary_search_by_key(&id.0, |d| d.id.0).ok()
}

/// Definition by id.
pub fn by_id(id: ChannelId) -> Option<&'static ChannelDef> {
    index_of(id).map(|i| &CHANNELS[i])
}

/// Definition by canonical name (`vehicle.speed_mps`).
pub fn by_name(name: &str) -> Option<&'static ChannelDef> {
    id_by_name(name).and_then(by_id)
}

/// Definition by export name (`Speed`, `TyrePressure_FL`).
pub fn by_export_name(export_name: &str) -> Option<&'static ChannelDef> {
    id_by_export_name(export_name).and_then(by_id)
}

/// The "no data" sample of every channel in registry order (what a fresh frame carries).
pub fn default_samples() -> Vec<Sample> {
    CHANNELS.iter().map(ChannelDef::default_sample).collect()
}

// ---------------------------------------------------------------------------------------------------------
// Groups
// ---------------------------------------------------------------------------------------------------------

/// Bits to shift an id right to get its group number (the high byte).
const GROUP_SHIFT: u16 = 8;

/// ID range group (the id's high byte).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum ChannelGroup {
    /// 0x0001-0x00FF: vehicle, driver inputs, aids/settings, identity, damage.
    VehicleInputs,
    /// 0x0100-0x01FF
    Powertrain,
    /// 0x0200-0x02FF
    Fuel,
    /// 0x0300-0x03FF: per-wheel tyre channels (stride 4) and per-axle tyre channels (0x03E0+).
    Tyres,
    /// 0x0400-0x04FF: per-wheel brake channels (stride 4) and brake settings (0x0480+).
    Brakes,
    /// 0x0500-0x05FF: G, rates, raw vectors, orientation, suspension, ride height, aero, wheels, slip.
    Dynamics,
    /// 0x0600-0x06FF
    HybridEnergy,
    /// 0x0700-0x07FF
    Timing,
    /// 0x0800-0x08FF: session and player race/scoring state.
    RaceScoring,
    /// 0x0900-0x09FF: weather and track conditions.
    Weather,
    /// 0x0A00-0x0AFF: track position and map.
    TrackPosition,
    /// 0x0B00-0x0BFF
    FlagsPit,
    /// 0x0C00-0x0CFF: derived fuel / stint / energy engine outputs.
    Strategy,
    /// 0x0D00-0x0DFF: application, network and recording diagnostics.
    Diagnostics,
}

impl ChannelGroup {
    /// Every group in id order.
    pub const ALL: [ChannelGroup; 14] = [
        ChannelGroup::VehicleInputs,
        ChannelGroup::Powertrain,
        ChannelGroup::Fuel,
        ChannelGroup::Tyres,
        ChannelGroup::Brakes,
        ChannelGroup::Dynamics,
        ChannelGroup::HybridEnergy,
        ChannelGroup::Timing,
        ChannelGroup::RaceScoring,
        ChannelGroup::Weather,
        ChannelGroup::TrackPosition,
        ChannelGroup::FlagsPit,
        ChannelGroup::Strategy,
        ChannelGroup::Diagnostics,
    ];

    /// Group of an id; `None` for the reserved id 0 and ids beyond the allocated ranges.
    pub const fn of(id: ChannelId) -> Option<Self> {
        if id.0 == 0 {
            return None;
        }
        let high = id.0 >> GROUP_SHIFT;
        let mut i = 0;
        while i < Self::ALL.len() {
            if Self::ALL[i].number() == high {
                return Some(Self::ALL[i]);
            }
            i += 1;
        }
        None
    }

    /// The high byte shared by every id in the group.
    pub const fn number(self) -> u16 {
        match self {
            ChannelGroup::VehicleInputs => 0x00,
            ChannelGroup::Powertrain => 0x01,
            ChannelGroup::Fuel => 0x02,
            ChannelGroup::Tyres => 0x03,
            ChannelGroup::Brakes => 0x04,
            ChannelGroup::Dynamics => 0x05,
            ChannelGroup::HybridEnergy => 0x06,
            ChannelGroup::Timing => 0x07,
            ChannelGroup::RaceScoring => 0x08,
            ChannelGroup::Weather => 0x09,
            ChannelGroup::TrackPosition => 0x0A,
            ChannelGroup::FlagsPit => 0x0B,
            ChannelGroup::Strategy => 0x0C,
            ChannelGroup::Diagnostics => 0x0D,
        }
    }

    /// Human-readable title.
    pub const fn title(self) -> &'static str {
        match self {
            ChannelGroup::VehicleInputs => "Vehicle & inputs",
            ChannelGroup::Powertrain => "Powertrain",
            ChannelGroup::Fuel => "Fuel",
            ChannelGroup::Tyres => "Tyres",
            ChannelGroup::Brakes => "Brakes",
            ChannelGroup::Dynamics => "Dynamics",
            ChannelGroup::HybridEnergy => "Hybrid & energy",
            ChannelGroup::Timing => "Timing",
            ChannelGroup::RaceScoring => "Session, race & scoring",
            ChannelGroup::Weather => "Weather & track conditions",
            ChannelGroup::TrackPosition => "Track position & map",
            ChannelGroup::FlagsPit => "Flags & pit",
            ChannelGroup::Strategy => "Derived fuel / stint / energy (engine outputs)",
            ChannelGroup::Diagnostics => "Application, network & recording diagnostics",
        }
    }

    /// Channels of this group, in id order.
    pub fn channels(self) -> impl Iterator<Item = &'static ChannelDef> {
        CHANNELS
            .iter()
            .filter(move |d| ChannelGroup::of(d.id) == Some(self))
    }
}

// ---------------------------------------------------------------------------------------------------------
// Wheels
// ---------------------------------------------------------------------------------------------------------

/// Wheel position, in LMU `mWheel[]` order (header: front left, front right, rear left, rear right).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Wheel {
    FrontLeft = 0,
    FrontRight = 1,
    RearLeft = 2,
    RearRight = 3,
}

impl Wheel {
    /// FL, FR, RL, RR.
    pub const ALL: [Wheel; 4] = [
        Wheel::FrontLeft,
        Wheel::FrontRight,
        Wheel::RearLeft,
        Wheel::RearRight,
    ];

    /// `mWheel[]` index and per-wheel id offset.
    pub const fn index(self) -> usize {
        self as usize
    }

    /// Export-name suffix (`FL`).
    pub const fn suffix(self) -> &'static str {
        match self {
            Wheel::FrontLeft => "FL",
            Wheel::FrontRight => "FR",
            Wheel::RearLeft => "RL",
            Wheel::RearRight => "RR",
        }
    }

    /// Canonical-name token (`fl`).
    pub const fn token(self) -> &'static str {
        match self {
            Wheel::FrontLeft => "fl",
            Wheel::FrontRight => "fr",
            Wheel::RearLeft => "rl",
            Wheel::RearRight => "rr",
        }
    }
}

/// Byte offset of a delimited wheel token (`fl` between `.`/`_` delimiters) in a canonical name.
fn wheel_token_offset(name: &str, token: &str) -> Option<usize> {
    let bytes = name.as_bytes();
    let is_delim = |b: u8| b == b'.' || b == b'_';
    name.match_indices(token).map(|(i, _)| i).find(|&i| {
        let before = i.checked_sub(1).map(|j| bytes[j]);
        let after = bytes.get(i + token.len()).copied();
        before.is_some_and(is_delim) && after.is_some_and(is_delim)
    })
}

/// The four channel ids (FL, FR, RL, RR) of a per-wheel group, given its front-left id. Returns `None` if
/// `front_left` is not the FL member of a stride-4 per-wheel group (checked against the canonical names).
pub fn wheel_group(front_left: ChannelId) -> Option<[ChannelId; 4]> {
    let fl = by_id(front_left)?;
    let at = wheel_token_offset(fl.name, Wheel::FrontLeft.token())?;
    let mut ids = [front_left; 4];
    for wheel in Wheel::ALL {
        let id = ChannelId(
            front_left
                .0
                .checked_add(u16::try_from(wheel.index()).ok()?)?,
        );
        let def = by_id(id)?;
        let token = wheel.token();
        let expected_matches = def.name.len() == fl.name.len()
            && def.name.get(..at) == fl.name.get(..at)
            && def.name.get(at..at + token.len()) == Some(token)
            && def.name.get(at + token.len()..) == fl.name.get(at + token.len()..);
        if !expected_matches {
            return None;
        }
        ids[wheel.index()] = id;
    }
    Some(ids)
}

// ---------------------------------------------------------------------------------------------------------
// Generated documentation (docs/CHANNEL_IDS.md)
// ---------------------------------------------------------------------------------------------------------

/// Decimal places kept when rendering numbers in the generated documentation.
const DOC_DECIMALS: usize = 6;

fn fmt_num(v: f64) -> String {
    if v == f64::INFINITY {
        return "∞".to_owned();
    }
    if v == f64::NEG_INFINITY {
        return "-∞".to_owned();
    }
    let s = format!("{v:.DOC_DECIMALS$}");
    let s = s.trim_end_matches('0').trim_end_matches('.');
    if s == "-0" {
        "0".to_owned()
    } else {
        s.to_owned()
    }
}

fn fmt_range(range: Option<(f64, f64)>) -> String {
    match range {
        None => String::new(),
        Some((lo, hi)) if hi == f64::INFINITY => format!("≥ {}", fmt_num(lo)),
        Some((lo, hi)) => format!("{} … {}", fmt_num(lo), fmt_num(hi)),
    }
}

/// Unit symbol for the docs; dimensionless kinds get a word so the column is never ambiguous.
fn doc_unit(unit: U) -> &'static str {
    match unit {
        U::None => "—",
        U::Fraction => "0..1",
        U::Count => "count",
        U::Enum => "enum",
        U::Text => "text",
        other => other.symbol(),
    }
}

fn push_line(out: &mut String, args: std::fmt::Arguments<'_>) {
    // Writing into a String cannot fail.
    let _ = out.write_fmt(args);
    out.push('\n');
}

/// Renders `docs/CHANNEL_IDS.md` from the registry. Deterministic: the golden-file test compares it.
pub fn channel_ids_markdown() -> String {
    let mut out = String::new();
    let o = &mut out;
    push_line(o, format_args!("# Channel IDs"));
    push_line(o, format_args!(""));
    push_line(
        o,
        format_args!(
            "<!-- GENERATED from crates/telemetry-model/src/registry.rs. Do not edit by hand: run \
             `LMURE_BLESS=1 cargo test -p telemetry-model --test registry_docs` to regenerate. -->"
        ),
    );
    push_line(o, format_args!(""));
    push_line(
        o,
        format_args!(
            "Telemetry schema version **{TELEMETRY_SCHEMA_VERSION}**, **{}** channels. Single source of truth: \
             `telemetry-model::registry` (D-017). IDs are append-only and never reused; per-wheel channels \
             use a stride of 4 (`FL, FR, RL, RR` = base + 0..3). Field semantics, raw units and evidence: \
             [LMU_CHANNEL_MAP.md](LMU_CHANNEL_MAP.md) (canonical names match).",
            CHANNELS.len()
        ),
    );
    push_line(o, format_args!(""));
    push_line(
        o,
        format_args!(
            "Columns: **Prov** M = measured (LMU, unit conversion only), D = derived, E = estimated. **Prio** network class. **Freq** PHY telemetry rate, SCO scoring rate, ENV slow, EVT event, STA static, DIA ~1 Hz diagnostics. **Int** C = continuous (may be interpolated), D = discrete (never interpolated). **Avail** A = always, V = vehicle-dependent, N = not provided by any live source (sent as NOT_SUPPORTED), X = experimental (not published until verified live). **Range** inclusive plausibility range in internal units (outside = INVALID). **Max rate** largest plausible change per second (larger jumps = INVALID)."
        ),
    );
    push_line(o, format_args!(""));
    push_line(o, format_args!("| Group | ID range | Channels |"));
    push_line(o, format_args!("|---|---|---:|"));
    for group in ChannelGroup::ALL {
        // Id 0 is reserved, so the first group starts at 0x0001.
        let first = (group.number() << GROUP_SHIFT).max(1);
        let last = first | 0x00FF;
        push_line(
            o,
            format_args!(
                "| {} | 0x{first:04X}–0x{last:04X} | {} |",
                group.title(),
                group.channels().count()
            ),
        );
    }
    for group in ChannelGroup::ALL {
        push_line(o, format_args!(""));
        push_line(
            o,
            format_args!(
                "## 0x{:04X} {}",
                group.number() << GROUP_SHIFT,
                group.title()
            ),
        );
        push_line(o, format_args!(""));
        push_line(
            o,
            format_args!(
                "| ID | Canonical name | Export | Label | Unit | Type | Source | Prov | Prio | Freq | Int | Avail \
                 | Range | Max rate/s | Origin |"
            ),
        );
        push_line(
            o,
            format_args!("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"),
        );
        for d in group.channels() {
            push_line(
                o,
                format_args!(
                    "| 0x{:04X} | `{}` | `{}` | {} | {} | {:?} | {} | {} | {:?} | {} | {} | {} | {} | {} | `{}` |",
                    d.id.0,
                    d.name,
                    d.export_name,
                    d.label,
                    doc_unit(d.unit),
                    d.value_type,
                    source_code(d.source),
                    provenance_code(d.provenance),
                    d.priority,
                    frequency_code(d.frequency),
                    interpolation_code(d.interpolation),
                    availability_code(d.availability),
                    fmt_range(d.valid_range),
                    d.max_rate_per_s.map(fmt_num).unwrap_or_default(),
                    d.origin,
                ),
            );
        }
    }
    out
}

fn source_code(s: Source) -> &'static str {
    match s {
        Source::LmuSharedMemoryTelemetry => "SM/tel",
        Source::LmuSharedMemoryScoring => "SM/sco",
        Source::LmuSharedMemoryGeneric => "SM/gen",
        Source::LmuRest => "REST",
        Source::Calculated => "CALC",
        Source::Application => "APP",
        Source::LmuDuckDb => "DuckDB",
    }
}

fn provenance_code(p: Provenance) -> &'static str {
    match p {
        Provenance::Measured => "M",
        Provenance::Derived => "D",
        Provenance::Estimated => "E",
    }
}

fn frequency_code(f: FrequencyClass) -> &'static str {
    match f {
        FrequencyClass::Physics => "PHY",
        FrequencyClass::Scoring => "SCO",
        FrequencyClass::Environment => "ENV",
        FrequencyClass::Event => "EVT",
        FrequencyClass::Static => "STA",
        FrequencyClass::Diagnostic => "DIA",
    }
}

fn interpolation_code(i: Interpolation) -> &'static str {
    match i {
        Interpolation::Continuous => "C",
        Interpolation::Discrete => "D",
    }
}

fn availability_code(a: Availability) -> &'static str {
    match a {
        Availability::Always => "A",
        Availability::VehicleDependent => "V",
        Availability::NotProvided => "N",
        Availability::Experimental => "X",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::value::Quality;

    #[test]
    fn lookups_agree() {
        for (i, def) in CHANNELS.iter().enumerate() {
            assert_eq!(index_of(def.id), Some(i));
            assert_eq!(
                by_name(def.name).map(|d| d.id),
                Some(def.id),
                "name {}",
                def.name
            );
            assert_eq!(
                by_export_name(def.export_name).map(|d| d.id),
                Some(def.id),
                "export {}",
                def.export_name
            );
        }
        assert!(by_id(ChannelId(0)).is_none());
        assert!(by_id(ChannelId(0xFFFF)).is_none());
        assert!(by_name("vehicle.speed").is_none());
        assert_eq!(by_name("vehicle.speed_mps").map(|d| d.id), Some(ch::SPEED));
        assert_eq!(
            by_export_name("TyreTemp_FL_Inner").map(|d| d.id),
            Some(ch::TYRE_TEMP_INNER_FL)
        );
    }

    #[test]
    fn spec_export_names_exist() {
        for export in [
            "Speed",
            "RPM",
            "Throttle",
            "Brake",
            "Steering",
            "Gear",
            "G_Lat",
            "G_Long",
            "YawRate",
            "Fuel",
            "FuelPerLap",
            "TyrePressure_FL",
            "TyreTemp_FL_Inner",
            "TyreTemp_FL_Middle",
            "TyreTemp_FL_Outer",
        ] {
            assert!(
                by_export_name(export).is_some(),
                "missing export name {export}"
            );
        }
    }

    #[test]
    fn names_are_well_formed() {
        for d in CHANNELS {
            let name_ok = d.name.split('.').count() >= 2
                && d.name.split('.').all(|part| {
                    !part.is_empty()
                        && part
                            .bytes()
                            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_')
                });
            assert!(
                name_ok,
                "canonical name {:?} must be dotted snake_case",
                d.name
            );
            let export_ok = d.export_name.len() <= 32
                && d.export_name
                    .bytes()
                    .next()
                    .is_some_and(|b| b.is_ascii_alphabetic())
                && d.export_name
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || b == b'_');
            assert!(
                export_ok,
                "export name {:?} must be MoTeC-safe (<= 32 chars, [A-Za-z0-9_])",
                d.export_name
            );
            assert!(!d.label.is_empty());
        }
    }

    #[test]
    fn origins_follow_conventions() {
        for d in CHANNELS {
            match (d.availability, d.source) {
                (Availability::NotProvided, _) => {
                    assert!(
                        d.origin.starts_with("unavailable:"),
                        "{}: {}",
                        d.name,
                        d.origin
                    );
                }
                (_, Source::Calculated) => {
                    let id = d.origin.strip_prefix("formula:").unwrap_or_default();
                    assert!(
                        !id.is_empty()
                            && id
                                .bytes()
                                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_'),
                        "{}: {}",
                        d.name,
                        d.origin
                    );
                    assert_ne!(
                        d.provenance,
                        Provenance::Measured,
                        "{} is calculated",
                        d.name
                    );
                }
                (_, Source::Application) => {
                    assert!(d.origin.starts_with("app:"), "{}: {}", d.name, d.origin);
                    assert_ne!(
                        d.provenance,
                        Provenance::Measured,
                        "{} is an application metric",
                        d.name
                    );
                }
                (_, src) if src.is_lmu_shared_memory() => {
                    assert_eq!(d.provenance, Provenance::Measured, "{}", d.name);
                    let root_ok = ["telemetry.", "scoring.", "generic.", "paths."]
                        .iter()
                        .any(|p| d.origin.starts_with(p));
                    assert!(root_ok, "{}: {}", d.name, d.origin);
                }
                (_, other) => panic!("{} has unexpected live source {other:?}", d.name),
            }
        }
    }

    #[test]
    fn discrete_and_typed_correctly() {
        for d in CHANNELS {
            if !d.is_float() {
                assert_eq!(
                    d.interpolation,
                    Interpolation::Discrete,
                    "{} is not a float",
                    d.name
                );
            }
            if matches!(d.frequency, FrequencyClass::Static | FrequencyClass::Event) {
                assert_eq!(
                    d.interpolation,
                    Interpolation::Discrete,
                    "{} is static/event",
                    d.name
                );
            }
            if d.max_rate_per_s.is_some() {
                assert!(
                    d.is_float(),
                    "{}: rate checks only apply to continuous floats",
                    d.name
                );
            }
        }
        // Spec §15: TC/ABS settings are separate channels from TC/ABS activity.
        let tc_level = by_id(ch::TC_LEVEL).map(|d| d.value_type);
        let tc_active = by_id(ch::TC_ACTIVE).map(|d| d.value_type);
        assert_eq!(tc_level, Some(T::U8));
        assert_eq!(tc_active, Some(T::Bool));
        assert_ne!(ch::ABS_LEVEL, ch::ABS_ACTIVE);
    }

    #[test]
    fn default_samples_are_never_zero() {
        let samples = default_samples();
        assert_eq!(samples.len(), CHANNELS.len());
        for (d, s) in CHANNELS.iter().zip(&samples) {
            assert_eq!(s.value, crate::value::Value::None);
            let expected = if d.availability == Availability::NotProvided {
                Quality::NotSupported
            } else {
                Quality::Unavailable
            };
            assert_eq!(s.quality, expected, "{}", d.name);
        }
    }

    #[test]
    fn per_wheel_groups_have_stride_four() {
        let mut groups = 0;
        for d in CHANNELS {
            if wheel_token_offset(d.name, Wheel::FrontLeft.token()).is_some() {
                let ids = wheel_group(d.id)
                    .unwrap_or_else(|| panic!("{} has no complete FR/RL/RR siblings", d.name));
                groups += 1;
                for wheel in Wheel::ALL {
                    let sib = by_id(ids[wheel.index()])
                        .unwrap_or_else(|| panic!("missing sibling of {}", d.name));
                    assert!(
                        sib.export_name.contains(wheel.suffix()),
                        "{} export must name {}",
                        sib.name,
                        wheel.suffix()
                    );
                    assert_eq!(
                        (sib.unit, sib.value_type, sib.source, sib.provenance),
                        (d.unit, d.value_type, d.source, d.provenance)
                    );
                    assert_eq!(
                        (sib.priority, sib.frequency, sib.availability),
                        (d.priority, d.frequency, d.availability)
                    );
                    assert_eq!(
                        (sib.valid_range, sib.max_rate_per_s),
                        (d.valid_range, d.max_rate_per_s)
                    );
                    if sib.source.is_lmu_shared_memory()
                        && sib.availability != Availability::NotProvided
                    {
                        let wheel_path = format!("mWheel[{}].", wheel.index());
                        assert!(
                            sib.origin.contains(&wheel_path),
                            "{} origin {} must read {}",
                            sib.name,
                            sib.origin,
                            wheel_path
                        );
                    }
                }
            }
        }
        assert!(
            groups >= 40,
            "expected the tyre/brake/suspension per-wheel groups, found {groups}"
        );
        assert!(
            wheel_group(ch::TYRE_PRESSURE_FR).is_none(),
            "FR is not a group base"
        );
        assert!(wheel_group(ch::SPEED).is_none());
        assert_eq!(
            wheel_group(ch::TYRE_PRESSURE_FL),
            Some([
                ch::TYRE_PRESSURE_FL,
                ch::TYRE_PRESSURE_FR,
                ch::TYRE_PRESSURE_RL,
                ch::TYRE_PRESSURE_RR
            ])
        );
    }

    #[test]
    fn groups_cover_every_channel() {
        let total: usize = ChannelGroup::ALL.iter().map(|g| g.channels().count()).sum();
        assert_eq!(total, CHANNELS.len());
        assert_eq!(
            ChannelGroup::of(ch::SPEED),
            Some(ChannelGroup::VehicleInputs)
        );
        assert_eq!(
            ChannelGroup::of(ch::TYRE_PRESSURE_FL),
            Some(ChannelGroup::Tyres)
        );
        assert_eq!(
            ChannelGroup::of(ch::REC_DURATION),
            Some(ChannelGroup::Diagnostics)
        );
        assert_eq!(ChannelGroup::of(ChannelId(0)), None);
        assert_eq!(ChannelGroup::of(ChannelId(0x0E00)), None);
        for g in ChannelGroup::ALL {
            assert!(g.channels().count() > 0, "{g:?} is empty");
        }
    }

    #[test]
    fn doc_number_formatting() {
        assert_eq!(fmt_num(150.0), "150");
        assert_eq!(fmt_num(-0.01), "-0.01");
        assert_eq!(fmt_num(TYRE_TEMP_MIN_C), "-73.15");
        assert_eq!(fmt_num(1.0e7), "10000000");
        assert_eq!(fmt_range(Some((0.0, f64::INFINITY))), "≥ 0");
        assert_eq!(fmt_range(None), "");
    }
}
